local _, ns = ...
local E = ns.DB.entries
E["npc:donova-snowden"] = {t="npc",n="Donova Snowden",z="winterspring",s="Donova Snowden is an intrepid dwarven researcher encamped alongside the thermal waters near Frostfire Hot Springs in Winterspring. Despite the bitter cold and hostile wildlife, she studies the strange thermal activity of the region and monitors the increasingly corrupted Winterfall furbolgs.",h="Donova Snowden is an intrepid dwarven researcher encamped alongside the thermal waters near Frostfire Hot...",sec={{t="A Lone Researcher in the Snow",b="While most travelers stick to the safety of Everlook, Donova Snowden has chosen to camp in the freezing wilderness near the Frostfire Hot Springs. She spends her days investigating the curious geothermic anomalies bubbling up through the permafrost, as well as the dark influences encroaching upon Winterspring's native wildlife. Practical and determined, she enlists passing adventurers of both the Alliance and the Horde to gather samples and help curb local threats.",sp=0},{t="Investigating the Winterfall",b="Much of Donova's attention centers on the Winterfall furbolgs, whose behavior has deteriorated into erratic aggression. Through investigating potent concoctions like Winterfall Firewater and strange toxic substances circulating among the tribes, she seeks to uncover the root cause behind their sudden fall into madness. Her field research makes her a critical contact for anyone hoping to understand the corruption spreading through the northern mountains.",sp=1}},faq={{q="Where can I find Donova Snowden?",a="Donova Snowden is camped by a small hot spring just southwest across the main road from the Frostfire Hot Springs in Winterspring.",al={"donova snowden location","where is donova","donova snowden map"}},{q="Why is Donova out here in the freezing cold?",a="She is conducting environmental research into Winterspring's unusual hot springs and investigating the corruption infecting the local Winterfall furbolg tribe.",al={"why is donova in winterspring","donova snowden purpose"}},{q="Will Donova work with Horde players?",a="Yes. While she is a dwarf, Donova operates as an independent researcher and offers tasks to both Alliance and Horde adventurers.",al={"is donova alliance only","can horde talk to donova","donova snowden faction"}},{q="What is Donova investigating regarding the Winterfall furbolgs?",a="She is studying the mysterious corruption driving the Winterfall tribe to madness, specifically looking into their strange concoctions like Winterfall Firewater and foul, toxic substances found among their runners.",al={"donova furbolg quest","winterfall firewater research"}}},ang={["race:Dwarf"]="Finding a fellow dwarf braving the frozen peaks alone feels familiar, showcasing the enduring dwarven appetite for fieldwork and exploration far from Khaz Modan.",["faction:Horde"]="Despite her dwarven heritage, Donova is willing to overlook faction allegiance to recruit capable scouts against the wild beasts and corrupted furbolgs of Winterspring."},kw={"donova snowden","firewater","frostfire hot springs","furbolg","researcher","winterfall","winterspring"},rel={"zone:winterspring","subzone:frostfire-hot-springs","topic:dwarf"},src={"Donova Snowden"}}
E["npc:rivern-frostwind"] = {t="npc",n="Rivern Frostwind",z="winterspring",s="Rivern Frostwind is a night elf riding instructor stationed high atop Frostsaber Rock in northern Winterspring. Accompanied by his frost tiger companion Glacier, he watches over the native wintersabers and trains riders deemed worthy by his order. Only the most dedicated champions of the Alliance are granted the honor of raising and riding one of his prized mounts.",h="Rivern Frostwind is a night elf riding instructor stationed high atop Frostsaber Rock in northern...",sec={{t="Master of the Frostsabers",b="Perched on the icy promontory of Frostsaber Rock, Rivern Frostwind oversees the breeding and stewardship of the legendary Winterspring frostsaber. While nightsabers roam the lush forests of Teldrassil and Ashenvale, their sub-arctic cousins are bred to endure the bitter cold of northern Kalimdor. Rivern acts as a gatekeeper for these majestic predators. He demands that outsiders prove their commitment to preserving the beasts—gathering fresh meat from the tundra, clearing out Winterfall furbolgs, and driving back rampaging frost giants—before he will even consider entrusting a cub to their care.",sp=0}},faq={{q="Who is Rivern Frostwind?",a="Rivern Frostwind is a night elf riding master and caretaker of the Wintersaber Trainers faction, situated at Frostsaber Rock in northern Winterspring. Alongside his loyal tiger Glacier, he ensures that the powerful native big cats are protected and properly reared.",al={"rivern frostwind lore","frostsaber trainer","who is rivern"}},{q="Why is he in Winterspring?",a="He lives at Frostsaber Rock to train and safeguard the region's rare white frostsabers. The predators face constant threats from aggressive Winterfall furbolgs, encroaching giants, and harsh conditions, so Rivern maintains order and looks after their well-being.",al={"why is rivern here","frostsaber rock purpose"}},{q="Can Horde players work with Rivern?",a="No. Rivern Frostwind is strictly loyal to the night elves and the Alliance. Horde travelers who approach Frostsaber Rock will find him completely unwilling to deal with them, reserving his trust and his mount training solely for Alliance champions.",al={"can horde get wintersaber","rivern horde friendly"}},{q="Who is the tiger beside him?",a="The frost tiger resting beside Rivern is Glacier, his personal companion and a prime specimen of the hardy cats indigenous to the Winterspring tundra.",al={"who is glacier","rivern frostwind tiger"}}},ang={["faction:Alliance"]="For the Alliance, Rivern Frostwind is the sole provider of the rare Winterspring Frostsaber, offering riders outside Darnassus a way to tame one of Kalimdor's fiercest beasts through sheer perseverance.",["race:NightElf"]="While nightsabers are deeply tied to the priesthood of Elune and the sentinels of Kalimdor, Rivern's frostsabers represent an adapted, solitary lineage bred specifically for the harsh snowscapes of Winterspring."},kw={"frostsaber rock","glacier","mount trainer","rivern frostwind","wintersaber trainers","winterspring frostsaber"},rel={"subzone:frostsaber-rock","zone:winterspring","topic:night-elf","topic:alliance"},src={"Rivern Frostwind"}}
E["subzone:ban-thallow-barrow-den"] = {t="subzone",n="Ban'Thallow Barrow Den",z="winterspring",s="Ban'Thallow Barrow Den is a subterranean sanctuary carved into the snow-covered cliffs behind Starfall Village in Winterspring. Built by the night elves to house sleeping druids communing with the Emerald Dream, the cavern currently sits largely quiet and unoccupied. It remains an enduring, sacred piece of kaldorei architecture amidst the harsh northern mountain winter.",h="Ban'Thallow Barrow Den is a subterranean sanctuary carved into the snow-covered cliffs behind Starfall...",sec={{t="A Silent Winter Sanctuary",b="Barrow dens across Kalimdor traditionally serve as peaceful resting chambers where druids slumber while their spirits roam the Emerald Dream. Ban'Thallow Barrow Den is tucked behind the ruins and settlements of Starfall Village, shielded from Winterspring's biting blizzards. In these post-Third War days, the subterranean halls remain silent and empty of sleeping druids, standing instead as a quiet testament to ancestral kaldorei heritage under the frost.",sp=0}},faq={{q="What is the purpose of Ban'Thallow Barrow Den?",a="Like other barrow dens built across northern Kalimdor, Ban'Thallow was created by night elf druids as a safe underground sanctuary to house their physical bodies while their spirits drifted through the Emerald Dream.",al={"why was ban'thallow built","what is this barrow den","ban'thallow purpose"}},{q="Are there any druids currently sleeping inside?",a="No. The subterranean halls of Ban'Thallow are currently quiet and empty of resting druids, left largely undisturbed behind Starfall Village.",al={"is anyone sleeping inside","are druids in ban'thallow","who is in the den"}},{q="Where exactly is Ban'Thallow Barrow Den located?",a="The den entrance is carved directly into the northern snowy bluffs situated just behind Starfall Village in eastern Winterspring, not far from the goblin trading post of Everlook.",al={"how to find ban'thallow","ban'thallow location","where is the barrow den"}}},ang={["race:NightElf"]="Barrow dens are sacred subterranean sanctuaries created to shelter the slumbering bodies of druids walking the Emerald Dream, making Ban'Thallow an important ancestral landmark in the cold north.",["class:Druid"]="Though currently silent and devoid of slumbering brothers and sisters, Ban'Thallow represents the long-standing tradition of druidic communion in even the most unforgiving corners of Kalimdor."},kw={"ban'thallow","barrow den","druid sanctuary","emerald dream","starfall village","winterspring"},rel={"subzone:starfall-village","zone:winterspring","topic:druid","subzone:everlook"},src={"Ban'Thallow Barrow Den"}}
E["subzone:darkwhisper-gorge"] = {t="subzone",n="Darkwhisper Gorge",z="winterspring",s="Darkwhisper Gorge is a treacherous, demon-infested ravine carved into the southern heights of Winterspring. When Archimonde was destroyed at the climax of the Third War, remnants of the shattered Burning Legion fled down the slopes of Mount Hyjal and entrenched themselves in these jagged chasms. Today, powerful fiends stalk its heights, guarding ancient minerals and dark planar relics.",h="Darkwhisper Gorge is a treacherous, demon-infested ravine carved into the southern heights of Winterspring.",sec={{t="A Legion Foothold in the Snow",b="Following the defeat of Archimonde atop Mount Hyjal, surviving demons of the Burning Legion scattered into the surrounding mountain ranges. A disciplined vanguard took refuge in Darkwhisper Gorge, transforming the southern border of Winterspring into a lethal stronghold. Led by Hederine demons—including lethal manastalkers, slayers, and initiates under Lady Hederine—these fiends fiercely defend their subterranean tunnels and fiery camps. Beyond the immediate threat of its elite inhabitants, an ominous, sealed archway stands at the gorge's lowest point, hinting at sealed passages leading higher up the sacred mountain.",sp=0},{t="Hidden Reagents and Rare Knowledge",b="Despite the overwhelming danger, brave adventurers and opportunists brave the gorge for its exceptional wealth. The ravines are rich in valuable minerals like truesilver and dense deposits of thorium. Deeper within its shadowed grottos, unusual inhabitants eke out an existence, such as the imp vendor Vi'el peddling fel-tainted reagents like felcloth and gromsblood, and the elusive high elf Earthcaller Franzahl, who possesses ancient metallurgical lore regarding the smelting of rare elementium.",sp=0}},faq={{q="Why are there so many demons in Winterspring?",a="The demons in Darkwhisper Gorge are survivors of the Burning Legion's invasion of Mount Hyjal during the Third War. After Archimonde was slain at the World Tree, his broken forces retreated down into these chasms to regroup rather than being entirely wiped out.",al={"why demons here","darkwhisper legion lore","where did the demons come from"}},{q="What is the sealed gate at the back of the gorge?",a="Deep within the southern depths of the gorge stands a runed archway and an active magical barrier. It guards the mountain pass leading directly up into Mount Hyjal, keeping mortals out of the sacred heights as the mountain recovers from the demonic assault.",al={"darkwhisper portal","instance portal winterspring","hyjal gate"}},{q="Who leads the demons here?",a="The encampment is dominated by a sect of demonic invaders known as the Hederine, seemingly commanded by Lady Hederine. They patrol the ravines alongside slayers, initiates, and fell hounds known as manastalkers.",al={"darkwhisper boss","hederine leader","who rules darkwhisper"}},{q="Why would an adventurer venture into Darkwhisper Gorge?",a="The area is exceptionally dangerous, requiring coordinated groups to navigate safely. However, it attracts warlocks seeking planar bindings, priests hunting the rare Eye of Shadow, blacksmiths and miners seeking rich thorium veins, and scholars seeking the hidden Earthcaller Franzahl.",al={"why go to darkwhisper","darkwhisper quests","darkwhisper rewards"}}},ang={["class:Warlock"]="The Hederine demons prowling these caverns hold vital planar components, making the gorge a primary proving ground for warlocks seeking mastery over greater summoning rituals like the Doomguard.",["profession:Mining"]="The perilous chasms conceal abundant deposits of truesilver and rich thorium veins, rewarding miners bold enough to sneak past elite demons."},kw={"burning legion","darkwhisper gorge","earthcaller franzahl","eye of shadow","hederine","lady hederine","mount hyjal","vi'el","winterspring"},rel={"zone:winterspring","subzone:frostwhisper-gorge","topic:burning-legion","topic:third-war","zone:blastedlands"},src={"Darkwhisper Gorge"}}
E["subzone:dun-mandarr"] = {t="subzone",n="Dun Mandarr",z="winterspring",s="Dun Mandarr is an abandoned dwarven camp situated before an icy cavern in south-eastern Winterspring. Established by the dwarf Jaron Stoneshaper, the site now sits in ruins after its occupants fled an onslaught of enraged local moonkin.",h="Dun Mandarr is an abandoned dwarven camp situated before an icy cavern in south-eastern Winterspring.",sec={{t="A Forsaken Camp",b="Bearing the traditional dwarven prefix 'Dun', Dun Mandarr was established by the explorer Jaron Stoneshaper as a base of operations in the frozen reaches of southeastern Winterspring. Stoneshaper's curiosity proved his undoing when he uncovered a relic known as the Blue-Feathered Amulet. The artifact's disturbance provoked the fury of the native wildkin, who descended upon the encampment in an uncontrollable rage. Overwhelmed and driven out, the dwarves abandoned the camp entirely. Today, no friendly souls remain among the snowbanks; ferocious, territorial moonkin guard the cavern and prowl the broken shelters.",sp=0}},faq={{q="What happened to the camp at Dun Mandarr?",a="Dun Mandarr was built by the dwarf explorer Jaron Stoneshaper. While excavating the area, he uncovered a mysterious Blue-Feathered Amulet. The relic deeply agitated the surrounding wildkin, who launched a furious assault on the settlement. Jaron and his companions were chased off, leaving the outpost abandoned and overrun.",al={"why is dun mandarr abandoned","who built dun mandarr","what is dun mandarr"}},{q="Why are there so many moonkin here?",a="The local wildkin hold the cavern and surrounding relics sacred. When Jaron Stoneshaper excavated the Blue-Feathered Amulet, the creatures flew into a violent frenzy to reclaim the artifact and protect their territory, driving out the intruders and claiming the camp as their own.",al={"why are there wildkin here","dun mandarr owlbeasts","why are owlbeasts attacking"}},{q="Where did Jaron Stoneshaper go?",a="After being driven from his camp by the rampaging moonkin, Jaron Stoneshaper retreated elsewhere into Winterspring to regroup and seek aid in recovering his stolen research and gear.",al={"where is jaron stoneshaper","jaron stoneshaper location"}}},ang={["race:Dwarf"]="The ruined site bears the traditional dwarven naming convention, serving as a harsh reminder of how easily archaeological ambition in ancient Kalimdor can turn disastrous.",["class:Druid"]="The moonkin guarding Dun Mandarr are fiercely protective of natural and celestial artifacts, reacting violently when sacred relics like the Blue-Feathered Amulet are disturbed by outsiders."},kw={"blue-feathered amulet","dun mandarr","dwarf camp","jaron stoneshaper","moonkin","wildkin","winterspring"},rel={"zone:winterspring"},src={"Dun Mandarr"}}
E["subzone:everlook"] = {t="subzone",n="Everlook",z="winterspring",s="Everlook is a snow-swept trading outpost in central Winterspring established by the Steamwheedle Cartel. Situated at the crossroads of the snowy valley's routes, it serves as a neutral haven for merchants, prospectors, and researchers braving the high-altitude cold.",h="Everlook is a snow-swept trading outpost in central Winterspring established by the Steamwheedle Cartel.",sec={{t="Commerce at the Edge of the World",b="Everlook represents the Steamwheedle Cartel's northernmost endeavor, mirroring outposts like Gadgetzan and Booty Bay under a blanket of permafrost. The walled settlement perches at the intersection of Winterspring's snowdrifts, operating under strictly enforced neutrality. It hosts the only operational bank and shared auction house services in the region, drawing both Alliance and Horde travelers in search of warmth and shelter. Guarded by hired bruisers, the town offers refuge from ferocious frostsabers and yetis, though High Overlord Saurfang has noted that much of the town's lucrative inventory actually relies on unsanctioned smuggler runs routed through corrupted Felwood.",sp=0},{t="Gears in the Tundra",b="Beneath its icy wooden roofs and whimsical penguin wallpaper, Everlook is a hotbed of technological curiosity. It houses specialized engineering workshops and advanced alchemical laboratories where goblin tinkerers push the boundaries of their craft away from prying eyes. Outside diplomacy has also begun knocking on the frost-rimmed gates; the Argent Dawn recently dispatched Gregor Greystone here to negotiate directly with town leadership, keeping a wary watch on the region's ancient ruins and gathering northern threats.",sp=0}},faq={{q="Who controls Everlook?",a="Everlook is owned and operated by the Steamwheedle Cartel. Unlike other goblin hubs governed by a solitary baron, local governance is informally handled by prominent merchants and workshop masters residing within the walls.",al={"who runs everlook","everlook leader","who is in charge of everlook"}},{q="Why is Everlook safe for both Alliance and Horde?",a="The Steamwheedle Cartel enforces strict commercial neutrality. Goblin bruisers quickly pummel anyone caught instigating violence within the walls, ensuring travelers of all allegiances can conduct trade unhindered.",al={"is everlook neutral","can horde and alliance visit everlook","everlook pvp rules"}},{q="Why is the Argent Dawn in Everlook?",a="The Argent Dawn maintains an official presence through emissary Gregor Greystone. He acts as their representative to the goblin merchants, securing access to regional supplies and monitoring local threats.",al={"what is argent dawn doing here","gregor greystone everlook","argent dawn winterspring"}},{q="Where does Everlook get its trade goods?",a="Beyond standard trade flights and surface caravans, town inventory is partly supplied through illicit smuggling routes winding out of the corrupted forests of Felwood, a fact known to veteran military observers like Varok Saurfang.",al={"everlook smuggling","winterspring trade goods","where do everlook goods come from"}}},ang={["profession:Engineering"]="Everlook is a major hub for high-level engineers, particularly those specializing in goblin engineering, who can learn to calibrate an ultra-safe transporter directly to the settlement."},kw={"everlook","goblin","gregor greystone","snow","steamwheedle cartel","trade outpost","winterspring"},rel={"zone:winterspring","topic:steamwheedle-cartel","topic:goblin","zone:felwood","subzone:gadgetzan","npc:varok-saurfang","topic:argent-dawn"},src={"Everlook"}}
E["subzone:frostfire-hot-springs"] = {t="subzone",n="Frostfire Hot Springs",z="winterspring",s="Frostfire Hot Springs are a curious series of steaming, geothermally heated pools nestled amidst the western snowdrifts of Winterspring. Despite the bitter sub-zero temperatures all around them, these waters bubble constantly, attracting curious scholars, hardy fishers, and hostile furbolgs alike.",h="Frostfire Hot Springs are a curious series of steaming, geothermally heated pools nestled amidst the western...",sec={{t="Steaming Waters in the Snow",b="Situated near the tunnel leading to Timbermaw Hold, Frostfire Hot Springs represent one of the strangest natural anomalies in northern Kalimdor. Thermal vents churn deep beneath the crust, feeding scalding water into several open pools while blizzards rage overhead. The local Winterfall furbolgs maintain a presence near the water, though their aggressive territorial nature makes approaching the warm banks hazardous for unwary travelers. For those able to navigate the hostile wildlife and winter chill, the unfrozen waters provide a rare haven for subterranean fish.",sp=0},{t="A Geothermal Mystery",b="The uncanny existence of such intense heat in an otherwise frozen wasteland has drawn the attention of curious observers. Nearby, an inquisitive dwarf named Donova Snowden keeps a lonely vigil over the springs, studying their origin and composition. Snowden suspects that these geothermal anomalies might not be entirely natural, hypothesizing that dark magical corruption seeping northward from the demonic stronghold of Darkwhisper Gorge could be responsible for roiling the subterranean waters.",sp=0}},faq={{q="Why are there hot springs in freezing Winterspring?",a="Deep thermal vents feed boiling mineral water to the surface faster than the sub-zero climate can freeze it. However, the exact magical or volcanic cause remains unconfirmed, prompting local researchers to investigate whether unnatural subterranean disturbances are involved.",al={"why is water hot","frostfire origin","hot water winterspring"}},{q="Who is Donova Snowden?",a="Donova Snowden is an Alliance-affiliated dwarven researcher encamped just east of the hot springs. She spends her days studying the unusual flora, fauna, and thermal properties of Winterspring, seeking to determine if dark forces are tampering with the land.",al={"dwarf near springs","donova snowden lore","hot springs questgiver"}},{q="Could the springs be tied to demonic magic?",a="Donova Snowden theorizes that the demonic taint festering in Darkwhisper Gorge far to the south may run deep through the earth, heating or distorting subterranean currents that bubble up at Frostfire Hot Springs.",al={"demon hot springs","darkwhisper connection","corrupted water"}},{q="Who lives around the hot springs?",a="The aggressive Winterfall furbolg tribe controls territory near the springs, viewing the warm pools as valuable ground. Travelers must remain on guard, as these furbolgs attack outsiders on sight.",al={"frostfire enemies","who controls hot springs","furbolgs hot springs"}}},ang={["race:Dwarf"]="The hot springs showcase the inquisitive nature of your kin, represented by Donova Snowden, who braves the frozen elements to unlock geological mysteries.",["class:Druid"]="Observing scalding waters in an arctic climate raises valid concerns regarding whether natural Ley lines or foul demonic energies from Darkwhisper Gorge are warping Kalimdor's balance."},kw={"darkwhisper gorge","donova snowden","frostfire hot springs","timbermaw hold","winterfall","winterspring"},rel={"npc:donova-snowden","zone:winterspring","subzone:timbermaw-hold","subzone:darkwhisper-gorge"},src={"Frostfire Hot Springs"}}
E["subzone:frostsaber-rock"] = {t="subzone",n="Frostsaber Rock",z="winterspring",s="Frostsaber Rock is a towering stone promontory rising above the snowy northern reaches of Winterspring. It serves as the primary sanctuary and training grounds for the noble frostsaber cats of the region.",h="Frostsaber Rock is a towering stone promontory rising above the snowy northern reaches of Winterspring.",sec={{t="A Perch in the Tundra",b="Rising high above the frozen wastes of northern Winterspring, Frostsaber Rock commands a sweeping view of the snowbound wild. The crag is named for the fierce, majestic frostsaber predators that prowl the slopes and valleys below. At its highest apex resides Rivern Frostwind, a solitary night elf dedicated to raising and tending these beasts. For champions loyal to the Alliance willing to brave the harsh conditions and prove their devotion, Rivern offers the rare privilege of learning to raise, tame, and ride one of these legendary snowy mounts.",sp=0}},faq={{q="Who lives atop Frostsaber Rock?",a="Rivern Frostwind makes his camp at the very summit of the rock. He is a trainer dedicated to the regional frostsaber cats and acts as a mentor for Alliance members seeking to earn a frostsaber companion.",al={"who is at frostsaber rock","frostsaber rock trainer","rivern location"}},{q="Can Horde players train beasts here?",a="No. Rivern Frostwind offers his training and companion beasts exclusively to trusted allies of the Alliance. Horde travelers will find no welcome on the summit.",al={"horde frostsaber rock","can horde get frostsaber","rivern horde"}},{q="What creatures are found around the rock?",a="The icy crag and surrounding plateaus are home to wild frostsaber cats, prowling the snowy terrain alongside other hardy beasts native to the harsh climate of Winterspring.",al={"what lives here","frostsaber rock beasts","frostsabers in winterspring"}},{q="Has anyone notable visited this summit?",a="The wandering beastmaster Rexxar is known to have traveled across Winterspring and climbed Frostsaber Rock during his solitary wanderings across Kalimdor.",al={"rexxar frostsaber rock","who visited frostsaber rock"}}},ang={["faction:Alliance"]="Alliance heroes who earn the trust of Rivern Frostwind atop the rock can undertake an arduous path of training to ride the famed Winterspring frostsaber.",["class:Hunter"]="The crag and its surrounding slopes offer an inspiring proving ground for hunters seeking to observe some of the fiercest predators native to northern Kalimdor."},kw={"alliance mount","frostsaber","frostsaber rock","rexxar","rivern frostwind","wintersaber","winterspring"},rel={"npc:rivern-frostwind","zone:winterspring","topic:alliance"},src={"Frostsaber Rock"}}
E["subzone:frostwhisper-gorge"] = {t="subzone",n="Frostwhisper Gorge",z="winterspring",s="Frostwhisper Gorge is a frigid canyon carved into the southern highlands of Winterspring, lying directly north of the sinister Darkwhisper Gorge. Ancient night elven ruins litter its icy floor and surrounding cliffs, while towering Frostmaul giants and frosty elementals dominate the chasm. High above the eastern rim, a solitary dwarf camp looks out over the precipice toward the ocean below.",h="Frostwhisper Gorge is a frigid canyon carved into the southern highlands of Winterspring, lying directly...",sec={{t="A Frozen Chasm of Ruins and Giants",b="Carved into the southern mountains of Winterspring, Frostwhisper Gorge serves as a threshold just before the demon-infested depths of Darkwhisper Gorge. Its snowy floor and cliffside ridges are strewn with the forgotten stonework of ancient night elven settlements. In the present day, the gorge is claimed by immense Frostmaul giants, their preservers, and icy elemental beings known as Ice Avatars, ruled by the monstrous Frostilicus. Travel down into the ravine is perilous, as the giants fiercely defend the frozen crags against any wandering intruders.",sp=0},{t="The Eastern Overlook",b="Hidden along a narrow, quiet track at the top of the gorge's eastern cliffs lies a curious outpost. Flying travelers on wyverns or gryphons passing between Azshara, Orgrimmar, and Winterspring often glimpse it from above: a solitary dwarven encampment perched at the very edge of the world. Planted with the banner of Ironforge, the camp features crates of provisions, barrels of ale, a comfortable chair, and a rifle leaning against the rest, providing an unmatched view across the drop to the Great Sea below.",sp=0}},faq={{q="What creatures live in Frostwhisper Gorge?",a="The canyon floor and surrounding terraces are inhabited by powerful Frostmaul giants, Frostmaul Preservers, and frosty elementals called Ice Avatars, led by a giant entity named Frostilicus.",al={"monsters in frostwhisper gorge","what lives in frostwhisper gorge","frostwhisper mobs"}},{q="Where is Frostwhisper Gorge located?",a="It is situated in the southern reach of Winterspring, cut into the icy cliffs just north of Darkwhisper Gorge.",al={"frostwhisper gorge location","where is frostwhisper gorge","frostwhisper map"}},{q="What is the small dwarf camp on the eastern cliffs?",a="Tucked away high on the eastern ridge overlooking the gorge is a tranquil campsite flying an Ironforge banner. It consists of a chair, a rifle, supply crates, and copious amounts of booze looking over the cliff edge toward the sea.",al={"dwarf camp winterspring","ironforge flag frostwhisper","eastern cliff camp"}},{q="Are there night elf ruins down in the gorge?",a="Yes. Crumbling night elven pillars and stonework are scattered across both the floor of the gorge and the upper cliff ridges, remnants of ancient Kaldorei habitations.",al={"elven ruins frostwhisper","night elf architecture winterspring gorge"}}},ang={["race:Dwarf"]="High atop the eastern edge of the chasm, an unknown dwarven traveler pitched camp with an Ironforge flag, a rifle, and plenty of ale to take in the vast view of the ocean.",["race:NightElf"]="The snowy depths of the gorge hold the shattered remnants of ancient night elf structures, now prowled by Frostmaul giants."},kw={"darkwhisper gorge","frostilicus","frostmaul","frostwhisper gorge","ice avatar","ironforge","winterspring"},rel={"subzone:darkwhisper-gorge","zone:winterspring","topic:night-elf","zone:ironforge","zone:azshara","zone:orgrimmar"},src={"Frostwhisper Gorge"}}
E["subzone:hidden-grove"] = {t="subzone",n="Hidden Grove",z="winterspring",s="Tucked away behind towering cliffs in northeastern Winterspring, the Hidden Grove is a secluded crater basin. Once an untroubled haven for Arctic hares, the basin has fallen under the domain of fiercely territorial wild moonkin.",h="Tucked away behind towering cliffs in northeastern Winterspring, the Hidden Grove is a secluded crater basin.",sec={{t="A Secluded Sanctuary",b="Walled off from the bitter howling winds of Winterspring, the Hidden Grove forms a sunken, snow-dusted forest crater that is nearly impossible to access from the outside cliffs. Travelers who discover its concealed rim must brave a sheer, dangerous drop or navigate a narrow cavern passage tucked into the southeastern ridge. Though the valley was long the undisturbed home of harmless white hares, aggressive wild moonkin have seized the glade, turning an isolated natural paradise into an ambush for unwary wanderers.",sp=0}},faq={{q="How do you get into the Hidden Grove?",a="The safest route into the grove is through a concealed cave nestled into the southeastern face of the surrounding cliff walls. While it is technically possible to scramble and drop down the steep cliff rim from above, doing so carries a high risk of fatal falls.",al={"how to enter hidden grove","hidden grove entrance","where is the cave"}},{q="What creatures live in the Hidden Grove?",a="The crater is heavily overrun by wild, hostile moonkin that vigorously guard the secluded valley. Before the moonkin moved in, the glade was celebrated as a peaceful haven populated almost entirely by harmless white hares.",al={"what is in hidden grove","hidden grove mobs","who lives here"}},{q="Where in Winterspring is this grove located?",a="The Hidden Grove lies in the far northeastern reaches of Winterspring, cupped entirely inside an isolated bowl of towering stone cliffs.",al={"hidden grove location","where is hidden grove"}}},ang={["class:Druid"]="The moonkin nesting inside the crater are a somber reminder of wild, untamed nature turned fiercely defensive, holding deep spiritual intrigue for practitioners of balance."},kw={"crater","hares","hidden grove","moonkin","winterspring"},rel={"zone:winterspring"},src={"Hidden Grove"}}
E["subzone:ice-thistle-hills"] = {t="subzone",n="Ice Thistle Hills",z="winterspring",s="The Ice Thistle Hills are a snow-covered highland rise lying just southeast of the goblin outpost of Everlook. Dominated by a rugged cavern system, the area is claimed by ferocious Ice Thistle yetis that threaten any travelers venturing off the main road.",h="The Ice Thistle Hills are a snow-covered highland rise lying just southeast of the goblin outpost of Everlook.",sec={{t="A Den of White Fur",b="Rising sharply out of the central drifts of Winterspring, the Ice Thistle Hills serve as the primary hunting grounds and nesting territory for the valley's aggressive Ice Thistle yetis. Centered around a prominent cave dug deep into the rockface, these hulking beasts roam both the rocky slopes and the winding tunnels within. Because of their proximity to Everlook, the yetis present a constant nuisance and danger to goblin commerce and visiting prospectors, who regularly commission intrepid hunters to cull the beasts for their valuable thick pelts and pristine horns.",sp=0}},faq={{q="Where are the Ice Thistle Hills located?",a="The Ice Thistle Hills are located directly southeast of the goblin trading post of Everlook in central Winterspring.",al={"ice thistle hills location","where is ice thistle hills","yeti cave location"}},{q="What creatures live here?",a="The slopes and the hill cavern are inhabited almost exclusively by Ice Thistle yetis, monstrous white-furred brutes that aggressively defend their territory.",al={"ice thistle monsters","what is in ice thistle hills","yeti types"}},{q="Why do adventurers hunt in the Ice Thistle Hills?",a="Travelers and tradesfolk based in Everlook frequently hire adventurers to collect the thick furs and pristine horns of the Ice Thistle yetis, which are prized for crafting and survival gear in the frigid valley.",al={"why kill yetis","yeti fur winterspring","ice thistle quest"}},{q="What resources can be gathered around the hills?",a="The outdoor slopes are home to rare alpine herbs such as Icecaps, while the deep recesses of the yeti cave harbor rich mineral deposits, including veins of thorium.",al={"herbs ice thistle","mining ice thistle cave"}}},ang={["profession:Mining"]="The dark cavern burrowed into the hill is a dangerous but rewarding destination for seasoned miners seeking rich veins of thorium guarded by yeti packs.",["profession:Herbalism"]="The freezing slopes surrounding the hills are prime ground for harvesting cold-weather flora like Icecaps, with rare blooms occasionally spotted near the cavern's mouth."},kw={"everlook","ice thistle hills","ice thistle yetis","icecaps","pristine yeti horn","thick yeti fur","winterspring","yeti cave"},rel={"subzone:everlook","zone:winterspring"},src={"Ice Thistle Hills"}}
E["subzone:lake-kel-theril"] = {t="subzone",n="Lake Kel'Theril",z="winterspring",s="Lake Kel'Theril is a vast, frozen lake nestled in the heart of Winterspring. Along its ice-locked shores stand ancient kaldorei ruins haunted by restless spirits who have lingered since the Great Sundering.",h="Lake Kel'Theril is a vast, frozen lake nestled in the heart of Winterspring.",sec={{t="A Frozen Tomb of the Highborne",b="Lake Kel'Theril is shrouded in eternal cold, its waters sealed under thick sheets of ice. Scattered across its surface and snowy banks are the shattered pillars and arches of ancient elven architecture. These are the remnants of Kel'Theril, once an outpost of the ancient Highborne civilization before the Great Sundering shattered Kalimdor. Rather than finding rest in death, the spirits of the fallen aristocracy wander the ice as tormented ghosts and specters, forever tethered to the tragic remnants of their former glory.",sp=0},{t="Restless Magic",b="The concentration of lingering arcane energy and restless ectoplasm makes the frozen lake a draw for occult researchers and adventurers alike.",sp=0}},faq={{q="Why is the lake haunted by night elves?",a="The spirits wandering Lake Kel'Theril are the tormented ghosts of ancient Highborne. When the Great Sundering tore Kalimdor apart ten thousand years ago, the catastrophic collapse of their civilization left their souls bound to the icy ruins of their former settlement.",al={"lake keltheril ghosts","why are there spirits here","winterspring lake ghosts"}},{q="What ruins stand along the lake's shores?",a="The crumbling pillars and stonework belong to the Ruins of Kel'Theril, an ancient kaldorei settlement that thrived during the reign of the Highborne prior to the War of the Ancients.",al={"ruins in the lake","what are the keltheril ruins"}},{q="Why do adventurers seek out the spirits here?",a="Scholars, arcanists, and armor crafters frequently seek the potent ectoplasm left behind by the restless Highborne phantoms to empower enchanted gear and magical relics.",al={"lake ectoplasm","why hunt spirits in winterspring"}}},ang={["race:NightElf"]="The tragic specters walking Lake Kel'Theril serve as a chilling reminder of the ruin brought about by the reckless arrogance of the ancient Highborne.",["class:Mage"]="The ethereal ectoplasm harvested from the lingering Highborne spirits here holds remarkable residual arcane resonance, ideal for advanced magical attunements."},kw={"ectoplasm","highborne","kel'theril","lake kel'theril","ruins of kel'theril","specters","winterspring"},rel={"subzone:ruins-of-kel-theril","zone:winterspring","topic:highborne","topic:night-elf"},src={"Lake Kel'Theril"}}
E["subzone:mazthoril"] = {t="subzone",n="Mazthoril",z="winterspring",s="Mazthoril is a massive, frostbitten cavern in central Winterspring that serves as the primary redoubt for the blue dragonflight in northern Kalimdor. Heavily guarded by dragonkin, spell-wielding wyrms, and arcane sentries, its winding ice tunnels conceal powerful magic and lead to the aerie of the reclusive blue matriarch Haleh.",h="Mazthoril is a massive, frostbitten cavern in central Winterspring that serves as the primary redoubt for the...",sec={{t="A Bastion of Blue Dragons",b="Carved into the frozen mountains just south of Everlook, Mazthoril houses an extensive brood answering to the Spell-Weaver, Malygos. The cavern and its surrounding crags are patrolled by vigilant drakes including Spellmaw, Azurous, and General Colbatann, while elite guardians watch the inner caverns. Intruders who wander into Mazthoril face dragonspawn thoroughly attuned to raw arcane energy, making any venture inside perilous without serious preparation.",sp=0},{t="The Teleportation Rune and the Matriarch",b="Deep inside the frozen labyrinth lies a mystical floor rune watched closely by drakes Manaclaw and Scryer. Stepping upon this rune transports travelers to an isolated mountain aerie above the cavern. There resides Haleh, a matriarch of the flight who maintains the guise of a high elf. Though naturally cautious toward mortals, Haleh possesses deep lore concerning draconic lineage and plays a critical role in unlocking the hidden ward protecting Onyxia's Lair.",sp=1}},faq={{q="Who rules Mazthoril?",a="Mazthoril is overseen by Haleh, a powerful blue dragon matriarch. She resides in an isolated aerie high above the cave complex, accessible only by a magical teleportation rune situated in the depths of the tunnels. When greeting mortal visitors, she appears in the form of a high elven woman.",al={"who leads mazthoril","who is the boss of mazthoril","mazthoril matriarch"}},{q="Why are blue dragons living in Winterspring?",a="The blue dragonflight, charged by the titans with guarding Azeroth's arcane magic, keeps a close watch on lingering fonts of ancient energy across the world. Winterspring holds remnants of the Highborne's ancient civilization around Lake Kel'Theril, making Mazthoril a natural stronghold for their sentinels in Kalimdor.",al={"why are there dragons in winterspring","why blue flight here","malygos brood winterspring"}},{q="How do you reach Haleh?",a="To reach Haleh, you must fight through the dragonkin to the back of Mazthoril's inner cavern. There, flanked by the drakes Manaclaw and Scryer, lies a glowing arcane rune on the floor. Stepping into the center of this rune teleports you to her high perch atop the mountain.",al={"reach haleh","get to haleh","teleport to haleh","where is haleh"}},{q="What role does Mazthoril play in entering Onyxia's Lair?",a="Alliance heroes seeking to enter Onyxia's Lair are eventually sent to consult Haleh. Possessing profound knowledge of the black dragonflight's wards, she assists Alliance champions in empowering the medallion needed to pass the threshold into Onyxia's Lair.",al={"onyxia key mazthoril","onyxia attunement haleh","drakefire amulet haleh"},sp=2}},ang={["faction:Alliance"]="Alliance heroes must seek out the matriarch Haleh in Mazthoril to complete their key to the black broodmother's lair.",["class:Mage"]="As the realm of Malygos's servants, Mazthoril is teeming with creatures saturated in pure arcane power, making it a site of great interest to scholars of the arcane."},kw={"blue dragonflight","colbatann","haleh","malygos","mazthoril","onyxia key","spellmaw","winterspring"},rel={"zone:winterspring","subzone:onyxia-s-lair","npc:onyxia","subzone:everlook","subzone:lake-kel-theril","topic:alliance"},src={"Mazthoril"}}
E["subzone:moon-horror-den"] = {t="subzone",n="Moon Horror Den",z="winterspring",s="Moon Horror Den is a secluded, frost-rimed cave located just northeast of the goblin trading post of Everlook in Winterspring. Tucked against the jagged mountainside, the cavern serves as a nesting hollow for ferocious raging owlbeasts. Travelers must take care when venturing near its icy mouth, as these territorial wildkin fiercely defend their shelter.",h="Moon Horror Den is a secluded, frost-rimed cave located just northeast of the goblin trading post of Everlook...",sec={{t="A Den of Feathers and Frost",b="Situated only a short trek northeast from Everlook's guarded gates, the Moon Horror Den cuts deep into the mountain rock. The cave is home to powerful raging owlbeasts—formidable wildkin known for their brute strength and feral disposition in the harsh snows of Winterspring. Although geographically close to the furbolg settlement of Winterfall Village to the south, the sheer mountain face creates an impassable natural barrier, ensuring the den remains an isolated refuge for the wildkin rather than a corridor of travel.",sp=0}},faq={{q="What creatures live in the Moon Horror Den?",a="The cavern is inhabited by raging owlbeasts, large and aggressive wildkin adapted to the freezing climate of Winterspring. These territorial beasts violently attack anyone wandering into their subterranean lair.",al={"what is in moon horror den","moon horror den mobs","owlbeasts in cave"}},{q="Where is the Moon Horror Den located?",a="It is located in eastern Winterspring, just a short walk northeast of the goblin town of Everlook. The mouth of the cave is nestled into the northern rock face.",al={"moon horror den location","how to find moon horror den","where is moon horror den"}},{q="Can you reach Winterfall Village from the den?",a="No. Although Winterfall Village lies directly south on the map, the high mountain ridge forms an impassable natural wall behind the den. Reaching the village requires traveling around the mountain slopes through the open valley.",al={"path to winterfall village","shortcut to winterfall","den to winterfall"}},{q="Why do travelers venture into this cave?",a="Adventurers typically enter the den to hunt the raging owlbeasts while assisting naturalists and researchers studying the corrupted or aggressive wildkin populations of Winterspring.",al={"why go to moon horror den","moon horror den quests"}}},ang={["class:Druid"]="As stewards of Elune's sacred creatures, druids find the violent frenzy of the owlbeasts dwelling in the den to be a sobering sight, reflecting the wild turbulence gripping Winterspring.",["class:Hunter"]="The cavern offers a tight, dangerous arena for tracking ferocious wildkin, where close-quarters combat against thick-hided owlbeasts tests any tracker's nerve."},kw={"cave","everlook","moon horror den","owlbeasts","raging owlbeast","wildkin","winterspring"},rel={"subzone:everlook","zone:winterspring","subzone:winterfall-village"},src={"Moon Horror Den"}}
E["subzone:owl-wing-thicket"] = {t="subzone",n="Owl Wing Thicket",z="winterspring",s="Owl Wing Thicket is a rugged cluster of caves and stone roosts in southern Winterspring. It is heavily populated by berserk, moontouched, and crazed owlbeasts that prowl the snowy crags. Deep within, ancient night elf altars preserve sacred knowledge about the origin of these creatures and their connection to the moon goddess Elune.",h="Owl Wing Thicket is a rugged cluster of caves and stone roosts in southern Winterspring.",sec={{t="Sanctuary of the Moonkin",b="Carved into the snowy highlands south of Everlook, Owl Wing Thicket serves as one of the densest nesting grounds for Winterspring's wild owlbeasts. Long ago, night elf caretakers revered these creatures as sacred guardians blessed by Elune. Ancient shrines and moonstone altars are still tucked among the cavern overhangs, watched over by the lingering spirits of the Guardians of Elune. Today, however, many of the beasts have succumbed to madness, lashing out at travelers who trespass upon their holy hollows.",sp=0},{t="The Lore of the Moonkin",b="Night elf scholars and priests travel to Owl Wing Thicket to seek communion with the Guardians of Elune. Guided by the priestess Ranshalla, Alliance seekers light the sacred braziers throughout the cavern complex to awaken ancient spirits. These guardians recount the legend of how the wild moonkin were first fashioned by Elune to safeguard pristine natural sanctuaries, offering clarity on the beasts' divine ancestry despite their present feral hostility.",sp=1}},faq={{q="What is Owl Wing Thicket?",a="Owl Wing Thicket is a network of snowy crags and caves in southern Winterspring. It is famous for its dense population of wild owlbeasts and several ancient shrines dedicated to the night elf goddess Elune.",al={"owl wing thicket","where is owl wing thicket","owl wing thicket lore"}},{q="Why are the owlbeasts here so aggressive?",a="While originally created as protectors of nature blessed by Elune, many of the owlbeasts in Winterspring have fallen into violent frenzy. In Owl Wing Thicket, they roam as crazed, berserk, and moontouched beasts, attacking anyone approaching their dens.",al={"why are moonkin mad","crazed owlbeasts winterspring","berserk owlbeasts"}},{q="Who is Ranshalla?",a="Ranshalla is a night elf priestess of Elune who journeys into Owl Wing Thicket. She seeks the guidance of the ancient Guardians of Elune to uncover the sacred origins and history of the moonkin race.",al={"ranshalla","who is ranshalla winterspring","priestess ranshalla"}},{q="What are the Guardians of Elune found inside the thicket?",a="The Guardians of Elune are ancient night elf spirits tied to altars within the caves. When summoned through the rekindling of sacred fires, they recount how the moonkin were created to watch over wild and holy lands.",al={"guardians of elune","spirits in owl wing thicket","moonkin spirits"}}},ang={["race:NightElf"]="For the Kaldorei, Owl Wing Thicket is holy ground gone wild, preserving early accounts of Elune's grace alongside feral moonkin who have lost their ancient balance.",["class:Druid"]="Druids hold the owlbeast form sacred, making this thicket a sobering site where creatures gifted with lunar affinity have slipped into unrestrained madness."},kw={"elune","guardians of elune","moonkin","moontouched","owl wing thicket","owlbeast","ranshalla","winterspring"},rel={"zone:winterspring","topic:elune","topic:night-elf","topic:alliance"},src={"Owl Wing Thicket"}}
E["subzone:ruins-of-kel-theril"] = {t="subzone",n="Ruins of Kel'Theril",z="winterspring",s="The Ruins of Kel'Theril are the shattered remnants of an ancient night elven city bordering the frozen expanse of Lake Kel'Theril in central Winterspring. Destroyed ten thousand years ago during the Great Sundering, its frostbitten stone pillars and temples remain haunted by the tormented spirits of Highborne who perished in the cataclysm.",h="The Ruins of Kel'Theril are the shattered remnants of an ancient night elven city bordering the frozen...",sec={{t="A Shattered Legacy",b="Long before Winterspring became a frozen highland, Kel'Theril stood as a grand settlement of the ancient night elven empire. When the Well of Eternity collapsed during the Great Sundering, the city was blasted into ruin and buried beneath ice and snow. The disaster caught the residing Highborne unaware, binding their souls to the snowbound stones. Today, the spirits of these former spellcasters linger among the frostbitten arches, endlessly reliving their final, catastrophic moments.",sp=0},{t="Echoes in the Snow",b="Travelers braving central Winterspring encounter restless, spectral Highborne haunting the ruined lakeside colonnades. These phantoms are often hostile, driven mad by millenniums of isolation and the violent magic that tore their civilization apart. However, a few sorrowful apparitions, such as the Remorseful Highborne, seek out travelers willing to hear their lingering laments and make peace with their forgotten past.",sp=0}},faq={{q="What happened to the city of Kel'Theril?",a="Kel'Theril was destroyed ten thousand years ago during the Great Sundering. When the Well of Eternity imploded and tore the ancient continent of Kalimdor apart, the city collapsed into rubble and was engulfed by the sudden bitter chill that settled over Winterspring.",al={"kel'theril history","why is kel'theril ruined","how did kel'theril fall"}},{q="What spirits haunt these ruins?",a="The ruins are haunted by the apparitions of Highborne night elves who were killed in the Great Sundering. Their souls remain tethered to the fallen stones, trapped in agony and wandering the snowy outskirts of Lake Kel'Theril.",al={"kel'theril ghosts","who haunts kel'theril","kel'theril undead"}},{q="Can you speak with any of the ghosts?",a="While most lingering spirits are hostile and lost to madness, a solitary Remorseful Highborne can be found among the ruins who is willing to speak with Alliance travelers seeking to understand the site's tragic past.",al={"friendly ghost kel'theril","remorseful highborne","ghost quests kel'theril"}},{q="Where are the ruins located?",a="The Ruins of Kel'Theril are situated along the shores of Lake Kel'Theril, a frozen lake nestled in the heart of central Winterspring.",al={"kel'theril location","where is kel'theril","find kel'theril"}}},ang={["race:NightElf"]="For night elves, Kel'Theril is a solemn reminder of the arrogance of the ancient Highborne caste and the horrific devastation wrought by their reckless use of arcane magic.",["class:Mage"]="Mages exploring the ruins will feel the ancient, dormant arcane energies that once sustained one of Kalimdor's proudest pre-Sundering magic cities."},kw={"ghosts","highborne","kel'theril","lake kel'theril","ruins","sundering","winterspring"},rel={"subzone:lake-kel-theril","zone:winterspring","topic:highborne","topic:alliance","topic:druid"},src={"Ruins of Kel'Theril"}}
E["subzone:starfall-village"] = {t="subzone",n="Starfall Village",z="winterspring",s="Starfall Village is a tranquil night elven sanctuary nestled along the snowy road of Winterspring. As the sole Alliance outpost in the frozen valley, it offers shelter and supplies to travelers braving the bitter northern chill. It also stands watch over the nearby Ban'Thallow Barrow Den.",h="Starfall Village is a tranquil night elven sanctuary nestled along the snowy road of Winterspring.",sec={{t="An Alliance Refuge in the Snow",b="Situated northwest of the goblin trading post of Everlook and south of Frostsaber Rock, Starfall Village represents the lone bastion of Alliance civilization in Winterspring. Composed of traditional night elven timber lodges, the settlement serves as a haven for wayfarers, providing critical supplies and a warm hearth amid the harsh mountain elements. Despite its peaceful appearance, the village remains ever vigilant, positioned adjacent to the Ban'Thallow Barrow Den where sleeping druids maintain their sacred vigil.",sp=0}},faq={{q="What is Starfall Village?",a="Starfall Village is a night elven enclave in Winterspring. It functions as the primary sanctuary and supply camp for the Alliance in the valley, providing lodging, trade, and guidance for scouts journeying toward Frostsaber Rock or investigating the nearby barrow dens.",al={"starfall","starfall town","what is this place"}},{q="Can Horde players use the amenities in Starfall Village?",a="No. Starfall Village is aligned strictly with the night elves and the Alliance. Horde travelers who stumble too close will be met with hostility by the local defenders.",al={"is starfall friendly to horde","can horde use starfall","starfall village horde"}},{q="What is the barrow den next to the village?",a="The cavern situated directly behind the village is the Ban'Thallow Barrow Den. Like other barrow dens constructed across Kalimdor, it serves as a sacred haven for night elven druids undertaking extended slumbers in the Emerald Dream.",al={"barrow den starfall","cave next to starfall","ban thallow"}},{q="Where is Starfall Village located?",a="The village sits along the main snow-covered road through Winterspring, situated northwest of the goblin settlement of Everlook and south of Frostsaber Rock.",al={"starfall location","how to get to starfall","where is starfall"}}},ang={["faction:Alliance"]="As the only Alliance settlement in Winterspring, Starfall Village offers vital respite, trade goods, and directions in an otherwise treacherous and remote highland wilderness.",["race:NightElf"]="For the night elves, Starfall is an important northern outpost that safeguards the sleeping druids resting within the adjacent Ban'Thallow Barrow Den."},kw={"alliance","ban'thallow","night elf","starfall","starfall village","winterspring"},rel={"zone:winterspring","subzone:ban-thallow-barrow-den","subzone:everlook","subzone:frostsaber-rock","topic:alliance"},src={"Starfall Village"}}
E["subzone:timbermaw-post"] = {t="subzone",n="Timbermaw Post",z="winterspring",s="Timbermaw Post is a small furbolg camp situated in the snowy expanse of Winterspring, nestled between Frostfire Hot Springs and Lake Kel'Theril. Despite bearing the name of the uncorrupted Timbermaw tribe, the encampment has fallen under the aggressive grip of the corrupted Winterfall furbolgs.",h="Timbermaw Post is a small furbolg camp situated in the snowy expanse of Winterspring, nestled between...",sec={{t="A Displaced Outpost",b="Positioned just southeast across the road from Frostfire Hot Springs and west of the frozen Lake Kel'Theril, Timbermaw Post stands as a bitter reminder of the furbolgs' internal strife in Winterspring. Its name clearly points to its original founders, the Timbermaw tribe—the last uncorrupted remnants of their kind clinging to sanity in northern Kalimdor. However, travelers approaching the camp will find no friendly welcomes. The outpost has been completely overtaken by the hostile Winterfall tribe, driven mad and violent by demonic corruption. Now crowded with savage Winterfall furbolgs, the camp serves as an aggressive staging ground encroaching upon the central road.",sp=0}},faq={{q="Why is it called Timbermaw Post if Winterfall furbolgs live here?",a="The settlement was originally established by the uncorrupted Timbermaw tribe. At some point, the violent, corrupted Winterfall furbolgs drove them out and claimed the camp for themselves, though the regional name on maps never changed.",al={"why timbermaw post","who owns timbermaw post","timbermaw post furbolgs"}},{q="Where is Timbermaw Post located?",a="It lies in central Winterspring, situated southeast across the main road from Frostfire Hot Springs and directly west of Lake Kel'Theril.",al={"timbermaw post location","where is timbermaw post","timbermaw post map"}},{q="Are the furbolgs at Timbermaw Post hostile?",a="Yes. Even if you have earned peaceful standing with the actual Timbermaw tribe, the furbolgs inhabiting this post belong to the hostile Winterfall tribe and will attack intruders on sight.",al={"are furbolgs here hostile","timbermaw post friendly","can i talk to timbermaw post"}}},ang={["class:Druid"]="For druids who revere the furbolgs as ancient stewards of nature, witnessing a Timbermaw camp captured by madness-driven Winterfall kin is a stark display of the Burning Legion's lingering taint."},kw={"frostfire hot springs","furbolg","lake kel'theril","timbermaw","timbermaw post","winterfall","winterspring"},rel={"topic:furbolg","zone:winterspring","subzone:frostfire-hot-springs","subzone:lake-kel-theril"},src={"Timbermaw Post"}}
E["subzone:winterfall-village"] = {t="subzone",n="Winterfall Village",z="winterspring",s="Winterfall Village is a sprawling furbolg encampment nestled in the snowdrifts of eastern Winterspring, just east of Everlook. Once peaceful kin to the other ursine tribes of Kalimdor, the Winterfall furbolgs living here have descended into madness and violent corruption under the rule of High Chief Winterfall.",h="Winterfall Village is a sprawling furbolg encampment nestled in the snowdrifts of eastern Winterspring, just...",sec={{t="A Tribe Consumed",b="Sprawled across the terraced snowbanks east of the goblin trading post Everlook, Winterfall Village serves as the primary bastion of the Winterfall furbolgs in Winterspring. Like their cousins scattered across northern Kalimdor, these bear-folk were warped and driven mad by the lingering foulness of the Burning Legion's invasion. Led by High Chief Winterfall from a secluded cavern atop the settlement's highest tier, the tribe has abandoned its ancestral ways. Instead of communing peacefully with the wild spirits of the snow, the enraged furbolgs now aggressively assault travelers, patrol the mountain passes, and threaten any who come near their frost-bitten home.",sp=0}},faq={{q="What is Winterfall Village?",a="It is the central settlement of the Winterfall furbolgs, located on the snowy slopes just east of the goblin outpost Everlook in Winterspring.",al={"winterfall village info","what is this place","furbolg town winterspring"}},{q="Why are the furbolgs here hostile?",a="The Winterfall furbolgs succumbed to corruption following the Third War. The demonic taint left behind by the Burning Legion warped their minds, stripping away their peaceful customs and leaving them violently hostile to all outsiders.",al={"why are furbolgs mad","corrupted furbolgs","why attack"}},{q="Who leads the village?",a="The tribe is ruled by High Chief Winterfall, who keeps watch over his followers from a small cave perched at the very peak of the settlement.",al={"who is the boss","winterfall leader","chief"}},{q="Why does Everlook care about this village?",a="The village sits uncomfortably close to Everlook. The crazed furbolgs constantly raid passing caravans, disrupt local trade routes, and threaten the goblins' mining and mercantile interests throughout eastern Winterspring.",al={"everlook goblins","why fight winterfall"}}},ang={["class:Druid"]="Seeing the deep corruption of the Winterfall tribe is a bitter tragedy, as furbolgs were ancient allies of the night elves and the Cenarion Circle before demonic madness took them.",["race:NightElf"]="The fall of the Winterfall tribe marks another painful fracture in the ancient bonds between the night elves and the native peoples of Kalimdor."},kw={"everlook","furbolg","high chief winterfall","winterfall","winterfall village","winterspring"},rel={"zone:winterspring","subzone:everlook","topic:furbolg"},src={"Winterfall Village"}}
E["zone:winterspring"] = {t="zone",n="Winterspring",z="winterspring",s="Winterspring is a vast, snow-covered valley nestled high along the northeastern slopes of Mount Hyjal, directly above the enchanted forests of Moonglade and Felwood. Known for its bitter cold, ancient Highborne ruins, and wandering apex predators, the region is anchored by the neutral goblin outpost of Everlook. It remains a land of fierce natural perils, sheltering remnants of the blue dragonflight while confronting demonic corruption along its southern heights.",h="Winterspring is a vast, snow-covered valley nestled high along the northeastern slopes of Mount Hyjal...",sec={{t="A Realm of Perpetual Frost",b="Perched thousands of feet above the surrounding wilderness, Winterspring rests beneath crisp mountain air and relentless snowstorms. Enormous exposed roots of the World Tree, Nordrassil, cut through the snowdrifts like towering wooden arches, warped and twisted during the climactic struggles of the Third War. While much of northern Kalimdor is dominated by dense woodlands and warm climates, Winterspring is a quiet land of medium alpine forests, rocky bluffs, and frozen lakes, home to formidable frostsabers, chimaeras, yetis, and thick-furred winter bears.",sp=0},{t="Crossroads and Outposts",b="Reaching this high plateau requires traversing the ancient carved passages of Timbermaw Hold, guarded by uncorrupted furbolgs who closely scrutinize any travelers passing from Felwood or Moonglade. At the valley's center sits Everlook, a thriving trading town operated by the Steamwheedle Cartel. Goblins welcome both Alliance and Horde adventurers with open registers, acting as an indispensable haven of engineering, trade, and warm fires against the biting mountain frost.",sp=0},{t="Old Ghosts and Blue Drakes",b="Centuries before modern settlements arose, ancient elves built the lakeside city of Kel'Theril. After reckless Highborne sorcerers shattered the cursed Crystal of Zin-Malor, madness claimed them, leaving restless phantoms to wander the ruined pillars and frozen waters to this day. Further south rise the cavernous heights of Mazthoril, the traditional Kalimdor stronghold of the blue dragonflight. Here, the brood of the Spell-Weaver Malygos, overseen by the matron protector Haleh, watches over arcane currents and contests local threats.",sp=0},{t="The Looming Shadow of the Gorge",b="The serenity of Winterspring is sharply broken along its southernmost border at Darkwhisper Gorge. There, elite demonic forces, remnant legions from the Third War, crawl along jagged canyons blocking the high approaches toward the summit of Mount Hyjal. Meanwhile, the native Winterfall furbolgs have succumbed to foul corruptions, prompting independent researchers like Donova Snowden to investigate the encroaching taint before the entire valley's wildlife is consumed.",sp=0}},faq={{q="How do I get to Winterspring?",a="Travelers must journey through Timbermaw Hold, a subterranean network of tunnels located in northeastern Felwood. Navigating the caves peacefully requires earning the trust of the native Timbermaw furbolgs, who will attack any trespassers they deem hostile. Once through the eastern exit, the snowy slopes of Winterspring open up immediately.",al={"getting to winterspring","how to enter winterspring","winterspring entrance","timbermaw tunnel winterspring"}},{q="Who runs the town of Everlook?",a="Everlook is managed by the Steamwheedle Cartel, the goblin trading conglomerate. Because of the goblins' strict profit motive and neutrality, both Horde and Alliance travelers can access its flight masters, repair vendors, banking vaults, and trade goods, provided visitors do not break the peace within town limits.",al={"who controls everlook","everlook faction","is everlook neutral"}},{q="What are the ghosts haunting Lake Kel'Theril?",a="They are the spirits of Highborne night elves who once inhabited the ancient city of Kel'Theril ten thousand years ago. When their sorcerers tampered with the stolen Crystal of Zin-Malor, its shattering unleashed a catastrophic curse. Subsequent expeditions of high elves centuries later were similarly driven to madness, doomed to haunt the frozen ruins alongside their ancestors.",al={"lake kel'theril ghosts","ruins of kel'theril spirits","who is at kel'theril"}},{q="Why are the Winterfall furbolgs aggressive?",a="The Winterfall furbolgs have succumbed to a spreading, unnatural corruption that has driven their clan into maddened hostility. While the nearby Timbermaw hold tightly to their sanity, the Winterfall have fallen under dark influences, prompting researchers like Donova Snowden to study their taint and clear their encampments.",al={"why are winterfall hostile","winterfall tribe corruption","donova snowden furbolgs"}},{q="What lives inside Mazthoril?",a="Mazthoril is the primary roost and sanctuary of the blue dragonflight on Kalimdor. Deep within its cavernous spires, wyrmkin, elite whelps, and ancient drakes guard powerful draconic relics and arcane secrets under the watchful eye of Haleh, consort to the Aspect Malygos.",al={"mazthoril dragons","what is mazthoril","blue dragons in winterspring"}},{q="What is Darkwhisper Gorge?",a="Darkwhisper Gorge is a treacherous canyon in the southernmost reaches of the valley, occupied by powerful elite demons leftover from the Third War. It serves as a heavily guarded perimeter along the treacherous trails leading toward the heights of Mount Hyjal.",al={"darkwhisper gorge demons","what is in darkwhisper gorge","hyjal gate winterspring"}},{q="Can you train or tame frostsabers here?",a="At Frostsaber Rock in the far northern reaches of the valley, the night elf Rivern Frostwind tends to the native white cats. Adventurers who assist him with securing provisions and safeguarding the pride may prove themselves worthy of learning the secrets to rearing and riding a Frostsaber.",al={"frostsaber mount","rivern frostwind frostsaber","how to get frostsaber"}}},ang={["profession:Herbalism"]="Winterspring is the only known habitat for Icecap, an indispensable alpine herb heavily sought after for advanced alchemical concoctions, along with scattered Mountain Silversage and rare Black Lotus blooms.",["profession:Mining"]="The icy crags and cavern walls across the valley are rich with valuable minerals, frequently yielding Small and Rich Thorium Veins alongside rare Truesilver deposits.",["race:NightElf"]="Winterspring is intimately tied to elven history, featuring the barrow dens where the Druids of the Talon rested for millennia, the tragic ruins of Kel'Theril, and exposed roots of Nordrassil damaged during the Battle of Mount Hyjal.",["class:Druid"]="Located high above Moonglade, Winterspring holds sacred significance as the place where Malfurion Stormrage awakened the Druids of the Talon from their ancient sleep during the Third War.",["faction:Alliance"]="Alliance heroes frequently visit Rivern Frostwind at Frostsaber Rock, working tirelessly in the extreme cold to earn the loyalty of the prestigious Winterspring Frostsaber mounts."},kw={"blue dragons","darkwhisper gorge","donova snowden","everlook","frostsaber","icecap","kel'theril","mazthoril","timbermaw","winterspring"},rel={"subzone:everlook","subzone:timbermaw-hold","subzone:mazthoril","subzone:darkwhisper-gorge","subzone:ruins-of-kel-theril","subzone:frostsaber-rock","npc:donova-snowden","npc:rivern-frostwind"},src={"Winterspring (Classic)","Winterspring"}}
